package com.mvt.backApp.agent.service;
import com.mvt.backApp.agent.dto.*;import com.mvt.backApp.agent.entity.*;import com.mvt.backApp.agent.repository.CarePartnerProfileRepository;import com.mvt.backApp.common.exception.ApiException;import com.mvt.backApp.security.model.AuthenticatedUser;import com.mvt.backApp.user.entity.User;import com.mvt.backApp.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class CarePartnerApprovalService{private final CarePartnerProfileRepository repository;private final UserRepository userRepository;
 @Transactional(readOnly=true)public Page<CarePartnerApplicationSummaryDto> findApplications(ApprovalStatus s,Pageable p){return repository.findAllByApprovalStatusOrderByCreatedAtDesc(s,p).map(this::summary);}@Transactional(readOnly=true)public CarePartnerApplicationDetailDto findByPartnerId(String id){return detail(required(id));}
 @Transactional public CarePartnerDecisionResponseDto approve(String id){CarePartnerProfile p=pending(id);LocalDateTime n=LocalDateTime.now();p.setApprovalStatus(ApprovalStatus.APPROVED);p.setApprovedBy(admin());p.setApprovedAt(n);p.setRejectionReason(null);repository.save(p);return decision(p,n);}
 @Transactional public CarePartnerDecisionResponseDto reject(String id,String reason){if(reason==null||reason.isBlank())throw new ApiException("REJECTION_REASON_REQUIRED","validation.rejectionReason.required",400);CarePartnerProfile p=pending(id);LocalDateTime n=LocalDateTime.now();p.setApprovalStatus(ApprovalStatus.REJECTED);p.setApprovedBy(admin());p.setApprovedAt(n);p.setRejectionReason(reason.trim());repository.save(p);return decision(p,n);}
 private CarePartnerProfile required(String id){return repository.findByPartnerId(id).orElseThrow(()->new ApiException("CARE_PARTNER_APPLICATION_NOT_FOUND","error.carePartner.applicationNotFound",404,id));}private CarePartnerProfile pending(String id){CarePartnerProfile p=required(id);if(p.getApprovalStatus()!=ApprovalStatus.PENDING)throw new ApiException("CARE_PARTNER_APPLICATION_ALREADY_REVIEWED","error.carePartner.applicationAlreadyReviewed",409);return p;}private User admin(){Object x=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(x instanceof AuthenticatedUser a))throw new ApiException("AUTHENTICATION_REQUIRED","error.authentication.required",401);return userRepository.findById(a.getUserId()).orElseThrow(()->new ApiException("AUTHENTICATED_USER_NOT_FOUND","error.authentication.required",401));}
 private CarePartnerApplicationSummaryDto summary(CarePartnerProfile p){return CarePartnerApplicationSummaryDto.builder().partnerId(p.getPartnerId()).firstName(p.getUser().getFirstName()).lastName(p.getUser().getLastName()).email(p.getUser().getEmail()).companyName(p.getCompanyName()).countryCode(p.getCountryCode()).approvalStatus(p.getApprovalStatus()).requestedAt(p.getCreatedAt()).build();}
 private CarePartnerApplicationDetailDto detail(CarePartnerProfile p){return CarePartnerApplicationDetailDto.builder().partnerId(p.getPartnerId()).firstName(p.getUser().getFirstName()).lastName(p.getUser().getLastName()).email(p.getUser().getEmail()).companyName(p.getCompanyName()).countryCode(p.getCountryCode()).mobileNumber(p.getMobileNumber()).whatsappNumber(p.getWhatsappNumber()).documentType(p.getDocumentType()).documentNumber(p.getDocumentNumber()).verificationDocumentPresent(p.getVerificationDocumentUrl()!=null).approvalStatus(p.getApprovalStatus()).approvedBy(p.getApprovedBy()==null?null:p.getApprovedBy().getId()).approvedAt(p.getApprovedAt()).rejectionReason(p.getRejectionReason()).requestedAt(p.getCreatedAt()).build();}private CarePartnerDecisionResponseDto decision(CarePartnerProfile p,LocalDateTime t){return CarePartnerDecisionResponseDto.builder().partnerId(p.getPartnerId()).approvalStatus(p.getApprovalStatus()).reviewedAt(t).build();}}
